public class BankAccountAggregate {
    private String accountId;
    private BigDecimal balance;
    private boolean isActive;

    public void deposit(BigDecimal amount) {
        if (!isActive) {
            throw new IllegalStateException("Account is inactive");
        }
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Deposit must be positive");
        }
        // Apply and emit the event instead of mutating state directly
        raiseEvent(new MoneyDepositedEvent(accountId, amount));
    }

    public void apply(MoneyDepositedEvent event) {
        this.accountId = event.getAccountId();
        this.balance = (this.balance == null) ? event.getAmount() : this.balance.add(event.getAmount());
        this.isActive = true;
    }
}
